python - <<'PY'
import numpy as np
from PIL import Image
A=np.array(Image.open('/app/output/main_final_canvas.png'));T=np.array(Image.open('/app/target.png'))
M=np.array(Image.fromarray((A[68:956,68:956].mean(2)<90).astype('uint8')*255).resize((1024,1024),Image.Resampling.NEAREST))>0
G=T.mean(2)<100
print('centroids actual,target',np.round([np.array(np.where(M)).mean(axis=1)[::-1],np.array(np.where(G)).mean(axis=1)[::-1]],1))
best=(0,None,None)
for dy in range(-22,23):
 for dx in range(-22,23):
  ys=slice(max(0,dy),min(1024,1024+dy)); yt=slice(max(0,-dy),min(1024,1024-dy));xs=slice(max(0,dx),min(1024,1024+dx));xt=slice(max(0,-dx),min(1024,1024-dx))
  q=(M[ys,xs]&G[yt,xt]).sum()
  if q>best[0]:best=(int(q),dx,dy)
print('best overlap dx dy',best,'boundary?',abs(best[1])==22 or abs(best[2])==22)
for dy,dx in [(0,0),(best[2],best[1])]:
 if dx>=0: Ma=np.pad(M[:,:1024-dx],((0,0),(dx,0)))
 else:Ma=np.pad(M[:,-dx:],((0,0),(0,-dx)))
 if dy>=0:Ma=np.pad(Ma[:1024-dy,:],((dy,0),(0,0)))
 else:Ma=np.pad(Ma[-dy:,:],((0,-dy),(0,0)))
 inter=(Ma&G).sum();iou=inter/(Ma|G).sum();print('shift',dx,dy,'IoU',iou,'recall',inter/G.sum(),'precision',inter/Ma.sum())
for name,y0,y1 in [('upper',180,360),('mid',320,470),('low',430,620),('stem',550,800)]:
 for q,a in [('G',G),('M',M)]:
  yy,xx=np.where(a[y0:y1]);xx+=0;yy+=y0
  if len(xx):print(name,q,'bbox',xx.min(),xx.max(),yy.min(),yy.max(),'area',len(xx))
PY
